mapper.select:
SELECT ftcr.id, ftcr.report_month as reportMonth, ftcr.shipment_id as shipmentId, ftcr.shipment_code as shipmentCode, ftcdr.asin, ftcdr.msku, ftcdr.fn_sku as fnSku, ftcdr.sku_id as skuId, ftcdr.sku_no as skuNo, ftcdr.after_end_period_transit_qty as afterEndPeriodTransitQty FROM fba_transit_calculate_report ftcr LEFT JOIN fba_transit_calculate_detail_report ftcdr ON ftcr.ID = ftcdr.main_id AND ftcdr.is_deleted = FALSE WHERE ftcr.is_deleted = FALSE AND ftcr.report_month = #{lastReportMonth} AND ftcdr.after_end_period_transit_qty > 0
AND ftcr.shipment_code = #{shipmentCode}
AND ftcdr.asin = #{asin}
AND ftcdr.msku = #{msku}

select ftcr.id, ftcr.report_month as reportMonth, to_char(ftcr.report_month, 'YYYY-MM') AS reportMonthStr, ftcr.shipment_code as shipmentCode, ftcr.shop_name as shopName, ftcr.customer_name as customerName, ftcr.shipment_status as shipmentStatus, ftcr.warehouse_name as warehouseName, ftcdr.id as detailId, ftcdr.asin, ftcdr.msku, ftcdr.fn_sku as fnSku, ftcdr.sku_no as skuNo, ftcdr.declare_qty as declareQty, ftcdr.delivery_qty as deliveryQty, ftcdr.receive_qty as receiveQty, ftcdr.diff_qty as diffQty, ftcdr.shipment_create_time as shipmentCreateTime, ftcdr.shipment_receive_time as shipmentReceiveTime, ftcdr.adjust_time as adjustTime, ftcdr.init_transit_qty as initTransitQty, ftcdr.current_delivery_qty as currentDeliveryQty, ftcdr.current_receive_qty as currentReceiveQty, ftcdr.end_period_transit_qty as endPeriodTransitQty, ftcdr.end_period_transit_adjust_qty as endPeriodTransitAdjustQty, ftcdr.after_end_period_transit_qty as afterEndPeriodTransitQty, ftcdr.adjust_reason as adjustReason from fba_transit_calculate_report ftcr LEFT JOIN fba_transit_calculate_detail_report ftcdr ON ftcr.id = ftcdr.main_id and ftcdr.is_deleted = FALSE where ${params.sqlMap.default} and ftcr.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ftcr.create_time desc,ftcr.shipment_code
